import * as path from "node:path";
import { expect } from "vitest";
import * as proto from "vscode-languageserver-protocol";
import { test } from "@clice/tools/testing";

// Initialize tolerates what newer clients send: unknown string enum values,
// integer enum values out of range, unknown fields, across the whole
// InitializeParams tree. The payloads were generated by walking the tree and
// injecting them.

interface Hostile {
    params: Record<string, unknown>;
}

for (const mode of ["unknown_string_enums", "out_of_range_int_enums", "unknown_fields"]) {
    test(mode, async (t) => {
        const hostile = JSON.parse(t.disk.read("hostile_init_params.json")) as Record<
            string,
            Hostile
        >;
        const s = await t.spawn();
        // The payload is the point: the handshake is sent as it stands,
        // only the workspace and process filled in.
        const result = (await s.client.sendRequest("initialize", {
            ...hostile[mode]?.params,
            processId: process.pid,
            rootPath: t.root,
            rootUri: s.uri(""),
            workspaceFolders: [{ uri: s.uri(""), name: "test" }],
            initializationOptions: {
                project: { cache_dir: path.join(t.root, ".clice"), test_hooks: true },
            },
        })) as proto.InitializeResult;
        expect(result.serverInfo?.name).toBe("clice");
        await s.client.sendNotification(proto.InitializedNotification.type, {});
        await t.show("diagnostics", s.diagnostics("main.cpp"));
    });
}
